#!/usr/bin/env pwsh
# ============================================================================
# Build master_client_handover_reset.sql from master_split/ files
# Usage: .\scripts\build_master_reset.ps1
# ============================================================================

$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent

$header = @"
-- ============================================================================
-- MASTER CLIENT HANDOVER RESET SCRIPT
-- Auto-generated by concatenating master_split files
-- Generated at: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
-- DO NOT EDIT THIS FILE DIRECTLY - Edit the files in master_split/ instead
-- Then run: scripts/build_master_reset.ps1
-- ============================================================================

"@

$splitDir = Join-Path $root 'supabase\scripts\master_split'
$outputFile = Join-Path $root 'supabase\scripts\master_client_handover_reset.sql'

$files = Get-ChildItem $splitDir -Filter '*.sql' | Where-Object { $_.Name -ne '03_master_cost_centers_and_rpcs.sql' } | Sort-Object Name

$output = $header
foreach ($f in $files) {
    Write-Host "  Adding: $($f.Name)" -ForegroundColor Cyan
    $output += "-- ============================================================================`n"
    $output += "-- FILE: $($f.Name)`n"
    $output += "-- ============================================================================`n`n"
    $output += (Get-Content $f.FullName -Raw)
    $output += "`n`n"
}

$output | Set-Content -Path $outputFile -Encoding UTF8

$info = Get-Item $outputFile
$lines = (Get-Content $outputFile).Count
Write-Host "`nGenerated: $outputFile" -ForegroundColor Green
Write-Host "  Lines: $lines | Size: $([math]::Round($info.Length/1024)) KB" -ForegroundColor Green
